  1	package commitgraph
  2	
  3	import (
  4		"bufio"
  5		"errors"
  6		"fmt"
  7		"io"
  8		"os"
  9		"path"
 10	
 11		"github.com/go-git/go-billy/v6"
 12	
 13		"github.com/go-git/go-git/v6/plumbing"
 14		"github.com/go-git/go-git/v6/utils/trace"
 15	)
 16	
 17	// OpenChainFile reads a commit chain file and returns a slice of the hashes within it
 18	//
 19	// Commit-Graph chains are described at https://git-scm.com/docs/commit-graph
 20	// and are new line separated list of graph file hashes, oldest to newest.
 21	//
 22	// This function simply reads the file and returns the hashes as a slice.
 23	// A hash of the other object format's width is rejected with
 24	// ErrObjectFormatMismatch.
 25	func OpenChainFile(r io.Reader, opts ...Option) ([]string, error) {
 26		o, err := readOptions(opts)
 27		if err != nil {
 28			return nil, err
 29		}
 30		chain, err := readChain(r, o, -1)
 31		if err != nil {
 32			return nil, err
 33		}
 34		return chain, nil
 35	}
 36	
 37	// readChain returns the graph hashes r lists, up to the first line that
 38	// fails to read or is not a hash of the configured object format. The
 39	// error describes that line; the hashes before it are returned with it.
 40	// If maxLines is not negative, at most that many lines are read and the
 41	// rest of r is ignored.
 42	func readChain(r io.Reader, o options, maxLines int) ([]string, error) {
 43		if r == nil {
 44			return nil, io.ErrUnexpectedEOF
 45		}
 46		bufRd := bufio.NewReader(r)
 47		chain := make([]string, 0, 8)
 48		for maxLines < 0 || len(chain) < maxLines {
 49			line, err := bufRd.ReadSlice('\n')
 50			if err != nil {
 51				if err == io.EOF {
 52					break
 53				}
 54				return chain, err
 55			}
 56	
 57			hashStr := string(line[:len(line)-1])
 58			if !plumbing.IsHash(hashStr) {
 59				return chain, ErrMalformedCommitGraphFile
 60			}
 61			if len(hashStr) != o.objectFormat.HexSize() {
 62				return chain, fmt.Errorf("%w: chain names %d-character graph hash, want %s", ErrObjectFormatMismatch, len(hashStr), o.objectFormat)
 63			}
 64			chain = append(chain, hashStr)
 65		}
 66		return chain, nil
 67	}
 68	
 69	// OpenChainOrFileIndex expects a billy.Filesystem representing a .git directory.
 70	// It will first attempt to read a commit-graph index file, before trying to read a
 71	// commit-graph chain file and its index files. Like Git, it falls back to the
 72	// chain whenever the index file cannot be opened or read. If the index file
 73	// exists but is unusable and there is no chain, the index file's error is
 74	// returned. Otherwise an Index will be returned.
 75	//
 76	// See: https://git-scm.com/docs/commit-graph
 77	func OpenChainOrFileIndex(fs billy.Filesystem, opts ...Option) (Index, error) {
 78		if _, err := readOptions(opts); err != nil {
 79			return nil, err
 80		}
 81		index, fileErr := openFileIndex(fs, opts...)
 82		if fileErr == nil {
 83			return index, nil
 84		}
 85	
 86		index, err := OpenChainIndex(fs, opts...)
 87		if err != nil && !errors.Is(fileErr, os.ErrNotExist) {
 88			if errors.Is(err, os.ErrNotExist) {
 89				return nil, fileErr
 90			}
 91			return nil, errors.Join(fileErr, err)
 92		}
 93		return index, err
 94	}
 95	
 96	func openFileIndex(fs billy.Filesystem, opts ...Option) (Index, error) {
 97		file, err := fs.Open(path.Join("objects", "info", "commit-graph"))
 98		if err != nil {
 99			return nil, err
100		}
101	
102		index, err := OpenFileIndex(file, opts...)
103		if err != nil {
104			_ = file.Close()
105			return nil, err
106		}
107		return index, nil
108	}
109	
110	// OpenChainIndex expects a billy.Filesystem representing a .git directory.
111	// It will read a commit-graph chain file and return a coalesced index.
112	//
113	// Like Git, it keeps the layers that load and stops at the first chain
114	// entry that is not a valid hash, or whose graph is missing, invalid or
115	// does not match the layers below it; the commits in the layers above are
116	// then simply not in the index, and a warning is traced. With
117	// WithStrictChain it returns ErrIncompleteChain instead. If the chain file
118	// is not present, or its first layer cannot be loaded, an error is
119	// returned.
120	//
121	// As in Git, only the chain file's first size/(hash length+1) lines are
122	// read, so a remainder too short to hold another entry, such as a trailing
123	// blank line, is ignored.
124	//
125	// See: https://git-scm.com/docs/commit-graph
126	func OpenChainIndex(fs billy.Filesystem, opts ...Option) (Index, error) {
127		o, err := readOptions(opts)
128		if err != nil {
129			return nil, err
130		}
131		chainFile, err := fs.Open(path.Join("objects", "info", "commit-graphs", "commit-graph-chain"))
132		if err != nil {
133			return nil, err
134		}
135	
136		// Like Git's load_commit_graph_chain_fd_st, read only as many lines as
137		// the file has room for whole entries, a hash and its newline; any
138		// shorter remainder, such as a trailing blank line, is ignored.
139		fi, err := chainFile.Stat()
140		if err != nil {
141			_ = chainFile.Close()
142			return nil, err
143		}
144		maxLines := int(fi.Size() / int64(o.objectFormat.HexSize()+1))
145		chain, readErr := readChain(chainFile, o, maxLines)
146		_ = chainFile.Close()
147		if len(chain) == 0 {
148			if readErr == nil {
149				readErr = ErrMalformedCommitGraphFile
150			}
151			return nil, readErr
152		}
153	
154		// incomplete reports that the chain stops below layer n (from 1), and
155		// why: an error with WithStrictChain, and a warning otherwise, as Git
156		// gives one.
157		incomplete := func(index Index, n int, cause error) (Index, error) {
158			err := fmt.Errorf("%w: layer %d: %w", ErrIncompleteChain, n, cause)
159			if o.strictChain {
160				_ = index.Close()
161				return nil, err
162			}
163			trace.General.Printf("commitgraph: %v", err)
164			return index, nil
165		}
166	
167		var index Index
168		for i, hash := range chain {
169			next, err := openChainLayer(fs, hash, index, opts...)
170			if err == nil && i > 0 {
171				// As in Git's add_graph_to_chain, a layer is added only while
172				// the chain names the layers below it after their trailers.
173				// The top layer's own name is never checked.
174				err = checkLayerName(chain[i-1], index)
175				if err != nil {
176					_ = closeTopLayer(next)
177				}
178			}
179			if err != nil {
180				if index == nil {
181					return nil, err
182				}
183				return incomplete(index, i+1, err)
184			}
185			index = next
186		}
187		if readErr != nil {
188			return incomplete(index, len(chain)+1, readErr)
189		}
190	
191		return index, nil
192	}
193	
194	// closeTopLayer closes the file of layer, the top of a chain, leaving the
195	// layers below it open: closing layer itself would close them too.
196	func closeTopLayer(layer Index) error {
197		return layer.(*fileIndex).reader.Close()
198	}
199	
200	// checkLayerName reports whether the chain names layer, the top of the
201	// chain loaded so far, after the checksum in its trailer. The trailer is
202	// read, not recomputed, so this catches a stale or mismatched layer, not a
203	// forged one.
204	func checkLayerName(name string, layer Index) error {
205		if want, _ := plumbing.FromHex(name); layer.(*fileIndex).graphOID != want {
206			return ErrMalformedCommitGraphFile
207		}
208		return nil
209	}
210	
211	// openChainLayer opens the graph the chain names hash on top of parent. On
212	// success the returned Index owns parent; on failure the caller keeps it.
213	func openChainLayer(fs billy.Filesystem, hash string, parent Index, opts ...Option) (Index, error) {
214		file, err := fs.Open(path.Join("objects", "info", "commit-graphs", "graph-"+hash+".graph"))
215		if err != nil {
216			return nil, err
217		}
218	
219		next, err := OpenFileIndexWithParent(file, parent, opts...)
220		if err != nil {
221			_ = file.Close()
222			return nil, err
223		}
224		return next, nil
225	}
