  4		"crypto"
  5	
  6		formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
  7	)
  8	
  9	// Option configures a commit-graph reader or encoder.
 10	type Option func(*options)
 11	
 12	type options struct {
 13		objectFormat formatcfg.ObjectFormat
 14		strictChain  bool
 15	}
 16	
 17	// WithObjectFormat selects the repository's object format, normally its
 18	// config's Extensions.ObjectFormat. The default, including UnsetObjectFormat,
 19	// is SHA-1. Readers reject graphs and chains of another format, and the
 20	// Encoder rejects object IDs of another width, with ErrObjectFormatMismatch.
 21	// Any format other than SHA-1 or SHA-256 makes readers and Encode return
 22	// formatcfg.ErrInvalidObjectFormat.
 23	func WithObjectFormat(of formatcfg.ObjectFormat) Option {
 24		return func(o *options) {
 25			o.objectFormat = of
 26		}
 27	}
 28	
 29	// WithStrictChain makes OpenChainIndex and OpenChainOrFileIndex return
 30	// ErrIncompleteChain when a layer above the first of a commit-graph chain
 31	// cannot be loaded or does not match the layers below it, as git
 32	// commit-graph verify does. By default the layers below are used, and the
 33	// commits in the layers above are not in the index, as for Git's other
 34	// commands.
 35	func WithStrictChain() Option {
 36		return func(o *options) {
 37			o.strictChain = true
 38		}
 39	}
 40	
 41	func readOptions(opts []Option) (options, error) {
 42		var o options
 43		for _, opt := range opts {
 44			if opt != nil {
 45				opt(&o)
 46			}
 47		}
 48		if o.objectFormat == formatcfg.UnsetObjectFormat {
 49			o.objectFormat = formatcfg.DefaultObjectFormat
 50		}
 51		if o.objectFormat != formatcfg.SHA1 && o.objectFormat != formatcfg.SHA256 {
 52			return o, formatcfg.ErrInvalidObjectFormat
 53		}
 54		return o, nil
 55	}
 56	
 57	func (o options) hashAlgorithm() crypto.Hash {
 58		if o.objectFormat == formatcfg.SHA256 {
 59			return crypto.SHA256
 60		}
 61		return crypto.SHA1
 62	}

